import * as THREE from 'three';
// Counters reset at the start of every render(); read them at the end of the world pass, not after the composer.
export const stats = { drawCalls: 0, triangles: 0, fps: 0 };
let frames = 0, acc = 0;
export function attachStats(scene, mainCamera) {
  scene.onAfterRender = (renderer, _scene, camera) => {
    if (camera !== mainCamera) return;                 // skip the mirror pass and shadow pre-passes
    stats.drawCalls = renderer.info.render.calls;
    stats.triangles = renderer.info.render.triangles;
  };
}
export function tickFps(dt) {
  acc += dt; frames++;
  if (acc >= 0.5) { stats.fps = Math.round(frames / acc); frames = 0; acc = 0; }
}
// Budget rules: one geometry + one material per prop family (InstancedMesh), triangles in the low hundreds of thousands,
// fix fps < ~50 before adding anything. Expose from the contract:
//   state() -> { ..., fps: stats.fps, drawCalls: stats.drawCalls, triangles: stats.triangles }
